      flashcards: [
        { id: 'fc-16-1', front: 'Ecuación 3.4 (suma de cuadrados)', back: '$\\sum_{j=1}^{n} j^{2} = \\dfrac{n(n+1)(2n+1)}{6}$, para $n \\in \\mathbb{N}$.' },
        { id: 'fc-16-2', front: 'Ejemplo 3.3 — paso base', back: '$\\dfrac{(1)(1+1)(2 \\cdot 1 + 1)}{6} = 1 = 1^{2}$, así que 3.4 vale para $n = 1$.' },
        { id: 'fc-16-3', front: 'Ejemplo 3.3 — factorización clave', back: '$2k^{2} + 7k + 6 = (2k+3)(k+2)$, que permite reescribir el resultado como $\\dfrac{(k+1)(k+2)[2(k+1)+1]}{6}$.' },
        { id: 'fc-16-4', front: 'Ejercicio 3.3 (los caballos)', back: 'Una “demostración” por inducción de que todos los caballos de un conjunto tienen el mismo color. El ejercicio consiste en encontrar el error del razonamiento.' },
        { id: 'fc-16-5', front: 'Conjuntos $S_1$ y $S_2$ del Ejercicio 3.3', back: '$S_1 = \\{h_1, \\dots, h_k\\}$ y $S_2 = \\{h_2, \\dots, h_{k+1}\\}$: ambos con $k$ caballos, para poder aplicarles la hipótesis inductiva.' },
        { id: 'fc-16-6', front: 'Ejercitación — sumas notables', back: '$2+4+\\dots+2n = n(n+1)$; $2+5+\\dots+(3n-1) = \\dfrac{n(3n+1)}{2}$; $1+3+\\dots+(2n-1) = n^{2}$; $1+2+4+\\dots+2^{n} = 2^{n+1}-1$.' },
        { id: 'fc-16-7', front: 'Ejercitación — desigualdades', back: '$\\left(\\dfrac{1}{2}\\right)^{n} < \\dfrac{1}{n}$ y $2^{n} < n!$ para $n > 4$ (esta última con base inductiva en $n = 5$).' },
      ],
