              '$\\cos\\phi = \\dfrac{|\\mathbf{u}||\\mathbf{v}|}{\\mathbf{u}\\cdot\\mathbf{v}}$',
              '$\\operatorname{sen}\\phi = \\dfrac{\\mathbf{u}\\cdot\\mathbf{v}}{|\\mathbf{u}||\\mathbf{v}|}$',
