            q: 'En el Ejemplo 4.3, ¿cuánto vale $\\mathbf{u}\\cdot\\mathbf{v}$ con $\\mathbf{u} = 2\\mathbf{i}+3\\mathbf{j}$ y $\\mathbf{v} = -7\\mathbf{i}+\\mathbf{j}$?',
            options: ['$-11$', '$-14$', '$17$', '$-17$'],
            correctIndex: 0,
